CREATE COLUMN TABLE "TEST_AP"."ONCM" ("AbsEntry" INTEGER CS_INT NOT NULL , "NcmCode" NVARCHAR(15) NOT NULL , "Descrip" NVARCHAR(254), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "GroupCode" NVARCHAR(1) DEFAULT 'L' NOT NULL , "Group" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ONCM_CODE" ON "TEST_AP"."ONCM" ( "NcmCode" ASC, "GroupCode" ASC )